    def _format_csv(self, columns: List[str], rows: List[Tuple]) -> str:
        """CSV format"""
        lines = []
        if self.header:
            lines.append(','.join(f'"{col}"' if ',' in col or '"' in col else col for col in columns))
        for row in rows:
            formatted = []
            for val in row:
                s = self.format_value(val)
                # Simple CSV escaping
                if ',' in s or '"' in s or '\n' in s:
                    s = '"' + s.replace('"', '""') + '"'
                formatted.append(s)
            lines.append(','.join(formatted))
        return '\n'.join(lines) if lines else ''

    def _format_json(self, columns: List[str], rows: List[Tuple]) -> str:
        """JSON array format"""
        result = []
        for row in rows:
            obj = {}
            for col, val in zip(columns, row):
                obj[col] = val
            result.append(obj)
        return json.dumps(result)

    def _format_jsonlines(self, columns: List[str], rows: List[Tuple]) -> str:
        """JSON lines format (one JSON object per line)"""
        lines = []
        for row in rows:
            obj = {}
            for col, val in zip(columns, row):
                obj[col] = val
            lines.append(json.dumps(obj))
        return '\n'.join(lines) if lines else ''

    def _format_list(self, columns: List[str], rows: List[Tuple]) -> str:
        """List format (pipe-separated)"""
        lines = []
        if self.header:
            lines.append(self.separator.join(columns))
        for row in rows:
            formatted = [self.format_value(val) for val in row]
            lines.append(self.separator.join(formatted))
        return '\n'.join(lines) if lines else ''

    def _format_ascii(self, columns: List[str], rows: List[Tuple]) -> str:
        """ASCII format (simple column-only)"""
        lines = []
