    if args.c or args.s:
        command = args.c or args.s
        try:
            cli.run_query(command)
        except Exception as e:
            if args.bail:
                sys.exit(1)
        sys.exit(0)

    # Process -f option
    if args.f:
        try:
            with open(args.f, 'r') as f:
