fn format_output_table(columns: &[String], rows: &[Vec<String>], options: &OutputOptions) -> String {
    if columns.is_empty() {
        return String::new();
    }

    let mut widths: Vec<usize> = columns.iter().map(|c| c.len()).collect();
    for row in rows {
        for (i, val) in row.iter().enumerate() {
            if i < widths.len() {
                widths[i] = widths[i].max(val.len());
            }
        }
    }

    let mut output = String::new();

    // Top border
    output.push('┌');
    for (i, w) in widths.iter().enumerate() {
        output.push_str(&"─".repeat(w + 2));
        if i < widths.len() - 1 {
            output.push('┬');
        }
    }
    output.push_str("┐\n");

    // Header
    output.push('│');
    for (col, w) in columns.iter().zip(widths.iter()) {
        output.push(' ');
        output.push_str(&format!("{:<width$}", col, width = w));
        output.push_str(" │");
    }
    output.push('\n');

    // Separator
    output.push('├');
    for (i, w) in widths.iter().enumerate() {
        output.push_str(&"─".repeat(w + 2));
        if i < widths.len() - 1 {
            output.push('┼');
        }
    }
    output.push_str("┤\n");

    // Rows
    for row in rows {
        output.push('│');
        for (val, w) in row.iter().zip(widths.iter()) {
            output.push(' ');
            output.push_str(&format!("{:>width$}", val, width = w));
            output.push_str(" │");
        }
        output.push('\n');
    }

    // Bottom border
    output.push('└');
    for (i, w) in widths.iter().enumerate() {
        output.push_str(&"─".repeat(w + 2));
        if i < widths.len() - 1 {
            output.push('┴');
        }
    }
    output.push_str("┘\n");

    output
}

fn execute_query(db: *mut sqlite3, query: &str, options: &OutputOptions) -> Result<(), String> {
    let c_query = CString::new(query).map_err(|_| "Invalid query".to_string())?;

    unsafe {
        let mut stmt: *mut sqlite3_stmt = ptr::null_mut();
        let mut pz_tail: *const c_char = ptr::null();

        let result = sqlite3_prepare_v2(db, c_query.as_ptr(), -1, &mut stmt, &mut pz_tail);
        if result != SQLITE_OK {
            let err = CStr::from_ptr(sqlite3_errmsg(db)).to_string_lossy();
            return Err(err.to_string());
        }

        if stmt.is_null() {
            return Ok(());
        }

        let col_count = sqlite3_column_count(stmt);
        let mut columns = Vec::new();

        for i in 0..col_count {
            let name = CStr::from_ptr(sqlite3_column_name(stmt, i))
                .to_string_lossy()
                .to_string();
            columns.push(name);
        }

        let mut rows: Vec<Vec<String>> = Vec::new();

        loop {
            let step_result = sqlite3_step(stmt);
            if step_result == SQLITE_DONE {
                break;
            } else if step_result == SQLITE_ROW {
                let mut row = Vec::new();
                for i in 0..col_count {
                    let col_type = sqlite3_column_type(stmt, i);
                    let value = match col_type {
                        SQLITE_NULL => options.nullvalue.clone(),
                        SQLITE_INTEGER => {
                            let val = sqlite3_column_int(stmt, i);
                            format!("{}", val)
                        }
                        SQLITE_FLOAT => {
                            let val = sqlite3_column_double(stmt, i);
                            format!("{}", val)
                        }
                        SQLITE_TEXT | SQLITE_BLOB => {
                            let ptr = sqlite3_column_text(stmt, i);
                            if ptr.is_null() {
                                options.nullvalue.clone()
                            } else {
                                CStr::from_ptr(ptr).to_string_lossy().to_string()
                            }
                        }
                        _ => options.nullvalue.clone(),
                    };
                    row.push(value);
                }
                rows.push(row);
            } else {
                let err = CStr::from_ptr(sqlite3_errmsg(db)).to_string_lossy();
                sqlite3_finalize(stmt);
                return Err(err.to_string());
            }
        }

        sqlite3_finalize(stmt);

        // Format and print output
        if !columns.is_empty() {
            match options.mode.as_str() {
                "csv" => {
                    if options.header {
                        println!("{}", columns.join(","));
                    }
                    for row in rows {
                        println!("{}", row.join(","));
                    }
                }
                "json" => {
                    print!("[");
                    for (idx, row) in rows.iter().enumerate() {
                        if idx > 0 {
                            print!(",");
                        }
                        print!("{{");
                        for (i, col) in columns.iter().enumerate() {
                            if i > 0 {
                                print!(",");
                            }
                            print!("\"{}\":{}", col, format_json_value(&row[i]));
                        }
                        print!("}}");
                    }
                    println!("]");
                }
                "list" => {
                    if options.header {
                        println!("{}", columns.join(&options.separator));
                    }
                    for row in rows {
                        println!("{}", row.join(&options.separator));
                    }
                }
                "table" | _ => {
                    print!("{}", format_output_table(&columns, &rows, options));
                }
            }
        }

        Ok(())
    }
}

