                        SQLITE_TEXT | SQLITE_BLOB => {
                            let ptr = sqlite3_column_text(stmt, i);
                            if ptr.is_null() {
                                options.nullvalue.clone()
                            } else {
                                CStr::from_ptr(ptr).to_string_lossy().to_string()
                            }
                        }
                        _ => options.nullvalue.clone(),
                    };
                    row.push(value);
                }
                rows.push(row);
            } else {
                let err = CStr::from_ptr(sqlite3_errmsg(db)).to_string_lossy();
                sqlite3_finalize(stmt);
                return Err(err.to_string());
            }
        }

        sqlite3_finalize(stmt);

        // Format and print output
        if !columns.is_empty() {
            match options.mode.as_str() {
                "csv" => {
                    if options.header {
                        println!("{}", columns.join(","));
                    }
                    for row in rows {
                        println!("{}", row.join(","));
                    }
                }
                "json" => {
                    print!("[");
                    for (idx, row) in rows.iter().enumerate() {
                        if idx > 0 {
                            print!(",");
                        }
                        print!("{{");
                        for (i, col) in columns.iter().enumerate() {
                            if i > 0 {
                                print!(",");
                            }
                            print!("\"{}\":{}", col, format_json_value(&row[i]));
                        }
                        print!("}}");
                    }
                    println!("]");
                }
                "list" => {
                    if options.header {
                        println!("{}", columns.join(&options.separator));
                    }
                    for row in rows {
                        println!("{}", row.join(&options.separator));
                    }
                }
                "table" | _ => {
                    print!("{}", format_output_table(&columns, &rows, options));
                }
            }
        }

        Ok(())
    }
}

fn format_json_value(val: &str) -> String {
    if val == "NULL" {
        "null".to_string()
    } else {
        format!("\"{}\"", val.replace("\"", "\\\""))
    }
}

