fn main() {
    let args: Vec<String> = env::args().collect();

    // Parse command line arguments
    let mut options = OutputOptions::default();
    let mut db_filename = String::new();
    let mut command: Option<String> = None;
    let mut file: Option<String> = None;
    let mut init_file: Option<String> = None;
    let mut cmd_option: Option<String> = None;
    let mut readonly = false;
    let mut no_stdin = false;
    let mut no_init = false;
    let mut bail_on_error = false;
    let mut storage_version = "v0.10.0".to_string();

    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];
        match arg.as_str() {
            "-version" => {
                print_version();
                process::exit(0);
            }
            "-h" | "-help" => {
                print_help();
                process::exit(0);
            }
            "-csv" => options.mode = "csv".to_string(),
            "-json" => options.mode = "json".to_string(),
            "-jsonlines" => options.mode = "jsonlines".to_string(),
            "-list" => options.mode = "list".to_string(),
            "-table" => options.mode = "table".to_string(),
            "-box" => options.mode = "box".to_string(),
            "-html" => options.mode = "html".to_string(),
            "-line" => options.mode = "line".to_string(),
            "-markdown" => options.mode = "markdown".to_string(),
            "-quote" => options.mode = "quote".to_string(),
            "-column" => options.mode = "column".to_string(),
            "-ascii" => options.mode = "ascii".to_string(),
            "-echo" => options.echo = true,
            "-header" => options.header = true,
            "-noheader" => options.header = false,
            "-readonly" => readonly = true,
            "-no-stdin" => no_stdin = true,
            "-no-init" => no_init = true,
            "-bail" => bail_on_error = true,
            "-separator" => {
                i += 1;
                if i < args.len() {
                    options.separator = args[i].clone();
                }
            }
            "-newline" => {
                i += 1;
                if i < args.len() {
                    options.newline = args[i].clone();
                }
            }
            "-nullvalue" => {
                i += 1;
                if i < args.len() {
                    options.nullvalue = args[i].clone();
                }
            }
            "-c" | "-s" => {
                i += 1;
                if i < args.len() {
                    command = Some(args[i].clone());
                }
            }
            "-f" => {
                i += 1;
                if i < args.len() {
                    file = Some(args[i].clone());
                }
            }
            "-init" => {
                i += 1;
                if i < args.len() {
                    init_file = Some(args[i].clone());
                }
            }
            "-cmd" => {
                i += 1;
                if i < args.len() {
                    cmd_option = Some(args[i].clone());
                }
            }
            "-storage-version" => {
                i += 1;
                if i < args.len() {
                    storage_version = args[i].clone();
                }
            }
            _ => {
                if !arg.starts_with('-') {
                    db_filename = arg.clone();
                    break;
                }
            }
        }
        i += 1;
    }

    if db_filename.is_empty() {
        eprintln!("Usage: duckdb [OPTIONS] FILENAME");
        process::exit(1);
    }

    unsafe {
        let mut db: *mut sqlite3 = ptr::null_mut();
        let c_filename = CString::new(&db_filename).unwrap();

        let open_flags = if readonly {
            SQLITE_OPEN_READONLY
        } else {
            SQLITE_OPEN_READWRITE | SQLITE_OPEN_CREATE
        };

        let result = sqlite3_open_v2(c_filename.as_ptr(), &mut db, open_flags, ptr::null());
        if result != SQLITE_OK {
            eprintln!("Error opening database");
            process::exit(1);
        }

        // Process init file
        if let Some(init) = init_file {
            if !no_init {
                if let Ok(content) = fs::read_to_string(&init) {
                    eprintln!("[90m-- Loading resources from {}[00m", init);
                    for query in content.split(';') {
                        if !query.trim().is_empty() {
                            let _ = execute_query(db, query.trim(), &options);
                        }
                    }
                }
            }
        }

        // Process cmd option
        if let Some(cmd) = cmd_option {
            let _ = execute_query(db, &cmd, &options);
        }

        // Process -c or -s option
        if let Some(cmd) = command {
            if options.echo {
                println!("{}", cmd);
            }
            let result = execute_query(db, &cmd, &options);
            if result.is_err() && bail_on_error {
                sqlite3_close(db);
                process::exit(1);
            }
            sqlite3_close(db);
            process::exit(0);
        }

        // Process -f option
        if let Some(file_path) = file {
            if let Ok(content) = fs::read_to_string(&file_path) {
                for query in content.split(';') {
                    if !query.trim().is_empty() {
                        if options.echo {
                            println!("{}", query.trim());
                        }
                        let result = execute_query(db, query.trim(), &options);
                        if result.is_err() && bail_on_error {
                            sqlite3_close(db);
                            process::exit(1);
                        }
                    }
                }
            }
            sqlite3_close(db);
            process::exit(0);
        }

        // Process -no-stdin option
        if no_stdin {
            sqlite3_close(db);
            process::exit(0);
        }

        // Read from stdin
        let stdin = io::stdin();
        let reader = BufReader::new(stdin.lock());
        let mut buffer = String::new();

        for line in reader.lines() {
            if let Ok(line) = line {
                buffer.push_str(&line);
                buffer.push('\n');

                if line.trim().ends_with(';') {
                    let query = buffer.trim_end_matches(';').trim();
                    if !query.is_empty() {
                        if options.echo {
                            println!("{}", query);
                        }
                        let result = execute_query(db, query, &options);
                        if result.is_err() && bail_on_error {
                            sqlite3_close(db);
                            process::exit(1);
                        }
                    }
                    buffer.clear();
                }
            }
        }

        // Check for remaining buffer
        if !buffer.trim().is_empty() {
            let query = buffer.trim_end_matches(';').trim();
            if !query.is_empty() {
                if options.echo {
                    println!("{}", query);
                }
                let result = execute_query(db, query, &options);
                if result.is_err() && bail_on_error {
                    sqlite3_close(db);
                    process::exit(1);
                }
            }
        }

        sqlite3_close(db);
    }
}
