class OutputFormatter:
    """Handles output formatting in various modes"""

    def __init__(self):
        self.mode = 'table'
        self.separator = '|'
        self.newline = '\n'
        self.nullvalue = 'NULL'
        self.header = True
        self.echo = False

    def set_mode(self, mode: str):
