    )

    # Options
    parser.add_argument('-ascii', action='store_true', help="set output mode to 'ascii'")
    parser.add_argument('-bail', action='store_true', help='stop after hitting an error')
    parser.add_argument('-batch', action='store_true', help='force batch I/O')
