    def format_output(self, columns: List[str], rows: List[Tuple], column_types: Optional[List[str]] = None) -> str:
        """Format output based on current mode"""
        if self.mode == 'csv':
            return self._format_csv(columns, rows)
        elif self.mode == 'json':
            return self._format_json(columns, rows)
        elif self.mode == 'jsonlines':
            return self._format_jsonlines(columns, rows)
        elif self.mode == 'list':
            return self._format_list(columns, rows)
        elif self.mode == 'table':
            return self._format_table(columns, rows, column_types)
        elif self.mode == 'box':
            return self._format_box(columns, rows)
        elif self.mode == 'html':
            return self._format_html(columns, rows)
        elif self.mode == 'line':
            return self._format_line(columns, rows)
        elif self.mode == 'markdown':
            return self._format_markdown(columns, rows)
        elif self.mode == 'quote':
            return self._format_quote(columns, rows)
        elif self.mode == 'column':
            return self._format_column(columns, rows)
        elif self.mode == 'ascii':
            return self._format_ascii(columns, rows)
        else:
            return self._format_table(columns, rows, column_types)

    def _format_csv(self, columns: List[str], rows: List[Tuple]) -> str:
        """CSV format"""
        lines = []
        if self.header:
            lines.append(','.join(columns))
        for row in rows:
            formatted = []
            for val in row:
                s = self.format_value(val)
                # Simple CSV escaping
                if ',' in s or '"' in s or '\n' in s:
                    s = '"' + s.replace('"', '""') + '"'
                formatted.append(s)
            lines.append(','.join(formatted))
        return '\n'.join(lines) if lines else ''

    def _format_json(self, columns: List[str], rows: List[Tuple]) -> str:
        """JSON array format"""
        result = []
        for row in rows:
            obj = {}
            for col, val in zip(columns, row):
                obj[col] = val
            result.append(obj)
        return json.dumps(result, separators=(',', ':'))

    def _format_jsonlines(self, columns: List[str], rows: List[Tuple]) -> str:
        """JSON lines format (one JSON object per line)"""
        lines = []
        for row in rows:
            obj = {}
            for col, val in zip(columns, row):
                obj[col] = val
            lines.append(json.dumps(obj, separators=(',', ':')))
        return '\n'.join(lines) if lines else ''

    def _format_list(self, columns: List[str], rows: List[Tuple]) -> str:
        """List format (pipe-separated)"""
        lines = []
        if self.header:
            lines.append(self.separator.join(columns))
        for row in rows:
            formatted = [self.format_value(val) for val in row]
            lines.append(self.separator.join(formatted))
        return '\n'.join(lines) if lines else ''

    def _format_ascii(self, columns: List[str], rows: List[Tuple]) -> str:
        """ASCII format (simple column-only)"""
        lines = []
        lines.extend(columns)
        for row in rows:
            for val in row:
                lines.append(self.format_value(val))
        return '\n'.join(lines) if lines else ''

    def _format_table(self, columns: List[str], rows: List[Tuple], column_types: Optional[List[str]] = None) -> str:
        """Table format with box drawing"""
        if not columns:
            return ''

        # Calculate column widths
        widths = [len(col) for col in columns]
        for row in rows:
            for i, val in enumerate(row):
                widths[i] = max(widths[i], len(self.format_value(val)))

        lines = []

        # Top border
        lines.append('┌' + '┬'.join('─' * (w + 2) for w in widths) + '┐')

        # Header
        header_cells = []
        for col, width in zip(columns, widths):
            header_cells.append(' ' + col.ljust(width) + ' ')
        lines.append('│' + '│'.join(header_cells) + '│')

        # Type row (if available) - simplified
        if column_types:
            type_cells = []
            for typ, width in zip(column_types, widths):
                type_cells.append(' ' + typ.ljust(width) + ' ')
            lines.append('│' + '│'.join(type_cells) + '│')

        # Separator
        lines.append('├' + '┼'.join('─' * (w + 2) for w in widths) + '┤')

        # Rows
        for row in rows:
            row_cells = []
            for val, width in zip(row, widths):
                formatted = self.format_value(val)
                row_cells.append(' ' + formatted.rjust(width) + ' ')
            lines.append('│' + '│'.join(row_cells) + '│')

        # Bottom border
        lines.append('└' + '┴'.join('─' * (w + 2) for w in widths) + '┘')

        return '\n'.join(lines)

    def _format_box(self, columns: List[str], rows: List[Tuple]) -> str:
        """Box format"""
        if not columns:
            return ''

        # Calculate column widths
        widths = [len(col) for col in columns]
        for row in rows:
            for i, val in enumerate(row):
                widths[i] = max(widths[i], len(self.format_value(val)))

        lines = []

        # Top border
        lines.append('+' + '+'.join('-' * (w + 2) for w in widths) + '+')

        # Header
        header_cells = []
        for col, width in zip(columns, widths):
            header_cells.append(' ' + col.ljust(width) + ' ')
        lines.append('|' + '|'.join(header_cells) + '|')

        # Separator
        lines.append('+' + '+'.join('-' * (w + 2) for w in widths) + '+')

        # Rows
        for row in rows:
            row_cells = []
            for val, width in zip(row, widths):
                formatted = self.format_value(val)
                row_cells.append(' ' + formatted.rjust(width) + ' ')
            lines.append('|' + '|'.join(row_cells) + '|')

        # Bottom border
        lines.append('+' + '+'.join('-' * (w + 2) for w in widths) + '+')

        return '\n'.join(lines)

    def _format_html(self, columns: List[str], rows: List[Tuple]) -> str:
        """HTML format"""
        lines = []
        lines.append('<tr><th>' + '</th><th>'.join(columns) + '</th>')
        lines.append('</tr>')
        for row in rows:
            formatted = [self.format_value(val) for val in row]
            lines.append('<tr><td>' + '</td><td>'.join(formatted) + '</td>')
            lines.append('</tr>')
        return '\n'.join(lines)

    def _format_line(self, columns: List[str], rows: List[Tuple]) -> str:
        """Line format"""
        lines = []
        for row in rows:
            for col, val in zip(columns, row):
                formatted = self.format_value(val)
                lines.append(f'    {col} = {formatted}')
        return '\n'.join(lines)

    def _format_markdown(self, columns: List[str], rows: List[Tuple]) -> str:
        """Markdown table format"""
        if not columns:
            return ''

        # Calculate column widths
        widths = [len(col) for col in columns]
        for row in rows:
            for i, val in enumerate(row):
                widths[i] = max(widths[i], len(self.format_value(val)))

        lines = []

        # Header
        header_cells = []
        for col, width in zip(columns, widths):
            header_cells.append(' ' + col.ljust(width) + ' ')
        lines.append('|' + '|'.join(header_cells) + '|')

        # Separator with right-alignment hints
        sep_cells = []
        for width in widths:
            sep_cells.append('-' * (width + 1) + ':')
        lines.append('|' + '|'.join(sep_cells) + '|')

        # Rows
        for row in rows:
            row_cells = []
            for val, width in zip(row, widths):
                formatted = self.format_value(val)
                row_cells.append(' ' + formatted.rjust(width) + ' ')
            lines.append('|' + '|'.join(row_cells) + '|')

        return '\n'.join(lines)

    def _format_quote(self, columns: List[str], rows: List[Tuple]) -> str:
        """Quote format (quoted headers)"""
        lines = []
        if self.header:
            quoted_cols = [f"'{col}'" for col in columns]
            lines.append(self.separator.join(quoted_cols))
        for row in rows:
            formatted = [self.format_value(val) for val in row]
            lines.append(self.separator.join(formatted))
        return '\n'.join(lines) if lines else ''

    def _format_column(self, columns: List[str], rows: List[Tuple]) -> str:
        """Column format (aligned columns)"""
        if not columns:
            return ''

        # Calculate column widths
        widths = [len(col) for col in columns]
        for row in rows:
            for i, val in enumerate(row):
                widths[i] = max(widths[i], len(self.format_value(val)))

        lines = []

        # Header
        header_parts = []
        for col, width in zip(columns, widths):
            header_parts.append(col.ljust(width))
        lines.append('  '.join(header_parts))

        # Separator
        sep_parts = []
        for width in widths:
            sep_parts.append('-' * width)
        lines.append('  '.join(sep_parts))

        # Rows
        for row in rows:
            row_parts = []
            for val, width in zip(row, widths):
                formatted = self.format_value(val)
                row_parts.append(formatted.ljust(width))
            lines.append('  '.join(row_parts))

        return '\n'.join(lines)


class DuckDBCLI:
    """Main DuckDB CLI implementation"""

    def __init__(self):
        self.formatter = OutputFormatter()
        self.conn = None
        self.bail_on_error = False
        self.readonly = False
        self.db_file = None
        self.init_file = None
        self.unredacted = False
        self.unsigned = False
        self.storage_version = 'v0.10.0'

    def connect(self, db_file: str):
        """Connect to database"""
        self.db_file = db_file

        if db_file == ':memory:':
            self.conn = sqlite3.connect(':memory:')
        else:
            # Check if file exists and if we're in readonly mode
            if self.readonly and not os.path.exists(db_file):
                raise RuntimeError(f"Cannot open {db_file} in read-only mode (file does not exist)")

            uri = f'file:{db_file}'
            if self.readonly:
                uri += '?mode=ro'

            self.conn = sqlite3.connect(uri, uri=True)

        # Enable foreign keys
        self.conn.execute('PRAGMA foreign_keys = ON')

    def execute_query(self, query: str) -> Tuple[List[str], List[Tuple]]:
        """Execute a query and return columns and rows"""
        if not self.conn:
            raise RuntimeError("Not connected to database")

        cursor = self.conn.cursor()
        cursor.execute(query)

        # Get column names
        columns = [desc[0] for desc in cursor.description] if cursor.description else []

        # Get rows
        rows = cursor.fetchall()

        return columns, rows

    def run_query(self, query: str, echo: bool = False):
        """Run a query and print results"""
        if not query.strip():
            return

        if echo or self.formatter.echo:
            print(query)

        try:
            columns, rows = self.execute_query(query)

            if columns:  # SELECT query
                # Get type information
                cursor = self.conn.cursor()
                cursor.execute(query)
                types = self._infer_column_types(cursor.description, rows)
                output = self.formatter.format_output(columns, rows, types)
                if output:
                    print(output)
            # For INSERT/UPDATE/DELETE, SQLite doesn't return rows

        except sqlite3.Error as e:
            error_msg = str(e)
            # Format error message to look like DuckDB
            if 'no such table' in error_msg.lower():
                table_name = self._extract_table_name(query)
                print(f"Catalog Error: Table with name {table_name} does not exist!", file=sys.stderr)
            else:
                print(f"Error: {error_msg}", file=sys.stderr)

            if self.bail_on_error:
                raise

    def run_multi_query(self, commands: str):
        """Run multiple queries separated by semicolons"""
        queries = commands.split(';')
        for query in queries:
            query = query.strip()
            if query:
                self.run_query(query)

    def _infer_column_types(self, description, rows) -> List[str]:
        """Infer column types from data"""
        types = []
        if not description:
            return types

        for i, desc in enumerate(description):
            # SQLite type mapping
            types.append(self._get_duckdb_type(rows, i if rows else -1))

        return types

    def _get_duckdb_type(self, rows: List[Tuple], col_idx: int) -> str:
        """Get DuckDB type name"""
        if col_idx < 0 or not rows:
            return 'unknown'

        # Sample values to determine type
        for row in rows[:100]:  # Sample first 100 rows
            if col_idx < len(row) and row[col_idx] is not None:
                val = row[col_idx]
                if isinstance(val, bool):
                    return 'boolean'
                elif isinstance(val, int):
                    return 'int32'
                elif isinstance(val, float):
                    return 'float64'
                elif isinstance(val, str):
                    return 'varchar'
                break

        return 'unknown'

    def _extract_table_name(self, query: str) -> str:
        """Extract table name from query"""
        match = re.search(r'(?:from|into)\s+(\w+)', query, re.IGNORECASE)
        if match:
            return match.group(1)
        return 'unknown'

    def process_init_file(self, filepath: str):
        """Process initialization file"""
        if not os.path.exists(filepath):
            raise RuntimeError(f"Initialization file {filepath} not found")

        print(f"[90m-- Loading resources from {filepath}[00m", file=sys.stderr)

        with open(filepath, 'r') as f:
            content = f.read()

        # Split by semicolons and execute
        self.run_multi_query(content)

    def interactive_mode(self):
        """Interactive REPL mode"""
        buffer = []
        while True:
            try:
                if not buffer:
                    prompt = '> '
                else:
                    prompt = '... '

                line = input(prompt)
                buffer.append(line)

                # Check if line ends with semicolon
                if line.rstrip().endswith(';'):
                    query = ' '.join(buffer)
                    self.run_query(query, echo=self.formatter.echo)
                    buffer = []
            except EOFError:
                break
            except KeyboardInterrupt:
                print()
                buffer = []
                continue


def main():
    # Handle version check early
    if len(sys.argv) > 1 and sys.argv[1] in ('--version', '-version'):
        print('v0.0.1 (Unknown Version) 780a7396')
        sys.exit(0)

    if len(sys.argv) > 1 and sys.argv[1] in ('--help', '-help', '-h'):
        print_help()
