    parser.add_argument('-no-init', action='store_true', help='skip processing the init file')
    parser.add_argument('-no-stdin', action='store_true', help='exit after processing options')
    parser.add_argument('-noheader', action='store_true', help='turn headers off')
    parser.add_argument('-nullvalue', metavar='TEXT', help="set text string for NULL values. Default 'NULL'")
    parser.add_argument('-quote', action='store_true', help="set output mode to 'quote'")
    parser.add_argument('-readonly', action='store_true', help='open the database read-only')
    parser.add_argument('-s', metavar='COMMAND', help='run "COMMAND" and exit')
    parser.add_argument('-safe', action='store_true', help='enable safe-mode')
    parser.add_argument('-separator', metavar='SEP', help="set output column separator. Default: '|'")
    parser.add_argument('-storage-version', metavar='VER', help="database storage version. Default: 'v0.10.0'")
    parser.add_argument('-table', action='store_true', help="set output mode to 'table'")
    parser.add_argument('-ui', action='store_true', help='launches a web interface')
    parser.add_argument('-unredacted', action='store_true', help='allow printing unredacted secrets')
    parser.add_argument('-unsigned', action='store_true', help='allow loading of unsigned extensions')

    # Positional arguments
    parser.add_argument('filename', nargs='?', help='database filename')
    parser.add_argument('sql', nargs='?', help='SQL command')

    args = parser.parse_args()

    # Require filename
    if not args.filename:
        parser.print_usage()
        sys.exit(1)

    # Create CLI instance
    cli = DuckDBCLI()
    cli.formatter.set_echo(args.echo)
    cli.bail_on_error = args.bail
    cli.readonly = args.readonly

    if args.storage_version:
        cli.storage_version = args.storage_version

    if args.unredacted:
        cli.unredacted = True

    if args.unsigned:
        cli.unsigned = True

    # Set output mode
    if args.ascii:
        cli.formatter.set_mode('ascii')
    elif args.csv:
        cli.formatter.set_mode('csv')
    elif args.json:
        cli.formatter.set_mode('json')
    elif args.jsonlines:
        cli.formatter.set_mode('jsonlines')
    elif args.list:
        cli.formatter.set_mode('list')
    elif args.html:
        cli.formatter.set_mode('html')
    elif args.line:
        cli.formatter.set_mode('line')
    elif args.markdown:
        cli.formatter.set_mode('markdown')
    elif args.quote:
        cli.formatter.set_mode('quote')
    elif args.column:
        cli.formatter.set_mode('column')
    elif args.box:
        cli.formatter.set_mode('box')
    elif args.table:
        cli.formatter.set_mode('table')

    # Set separator
    if args.separator:
        cli.formatter.set_separator(args.separator)

    # Set newline
    if args.newline:
        cli.formatter.set_newline(args.newline)

    # Set null value
    if args.nullvalue:
        cli.formatter.set_nullvalue(args.nullvalue)

    # Set headers
    if args.header:
        cli.formatter.set_header(True)
    elif args.noheader:
        cli.formatter.set_header(False)

    # Connect to database
    try:
        cli.connect(args.filename)
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

    # Process init file
    if args.init and not args.no_init:
        try:
            cli.process_init_file(args.init)
        except Exception as e:
            print(f"Error: {e}", file=sys.stderr)
            if args.bail:
                sys.exit(1)

    # Process -cmd option
    if args.cmd:
        try:
            cli.run_multi_query(args.cmd)
        except Exception as e:
            if args.bail:
                sys.exit(1)

    # Process -c or -s option
    if args.c or args.s:
        command = args.c or args.s
        try:
            cli.run_multi_query(command)
        except Exception as e:
            if args.bail:
                sys.exit(1)
        sys.exit(0)

    # Process -f option
    if args.f:
        try:
            with open(args.f, 'r') as f:
                content = f.read()
            cli.run_multi_query(content)
        except Exception as e:
            print(f"Error: {e}", file=sys.stderr)
            if args.bail:
                sys.exit(1)
        sys.exit(0)

    # Process -no-stdin option
    if args.no_stdin:
        sys.exit(0)

    # Interactive mode or read from stdin
    try:
        if sys.stdin.isatty() or args.interactive:
            cli.interactive_mode()
        else:
            # Read from stdin
            content = sys.stdin.read()
            cli.run_multi_query(content)
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        if args.bail:
            sys.exit(1)


