                sys.exit(1)

    # Process -c or -s option
    if args.c or args.s:
        command = args.c or args.s
        try:
            cli.run_multi_query(command)
        except Exception as e:
            if args.bail:
                sys.exit(1)
        sys.exit(0)

    # Process -f option
    if args.f:
        try:
            with open(args.f, 'r') as f:
                content = f.read()
            cli.run_multi_query(content)
        except Exception as e:
            print(f"Error: {e}", file=sys.stderr)
            if args.bail:
                sys.exit(1)
        sys.exit(0)

    # Process -no-stdin option
    if args.no_stdin:
        sys.exit(0)

    # Interactive mode or read from stdin
    try:
        if sys.stdin.isatty() or args.interactive:
            cli.interactive_mode()
        else:
            # Read from stdin
            content = sys.stdin.read()
            cli.run_multi_query(content)
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        if args.bail:
            sys.exit(1)


